import{_ as o}from"./chunks/field-pt.C7x8tUka.js";import{_ as e,o as r,c as t,a2 as s}from"./chunks/framework.DHtetOlu.js";const h=JSON.parse('{"title":"Introdução","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),i={name:"guide/index.md"};function d(n,a,l,m,c,u){return r(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="introducao" tabindex="-1">Introdução <a class="header-anchor" href="#introducao" aria-label="Permalink to &quot;Introdução&quot;">​</a></h1><p>O <strong>MagFEM</strong> resolve problemas de campo magnético em duas dimensões pelo método dos elementos finitos, direto no navegador. Serve para indutores, transformadores, atuadores, contatores e, mais adiante, máquinas girantes. Os problemas podem ser <strong>planos</strong> (seção transversal com profundidade) ou <strong>axissimétricos</strong> (sólidos de revolução em torno do eixo z).</p><ul><li><strong>Sem instalação e sem servidor.</strong> O núcleo numérico (C++ e Eigen) é compilado para WebAssembly e roda num Web Worker. O projeto fica na sua máquina, como no draw.io.</li><li><strong>Português e inglês</strong>, tema claro e escuro, e o botão <strong>Citar</strong> no topo.</li><li><strong>Código aberto</strong> (MIT) no <a href="https://github.com/thalesmaoa/magfem" target="_blank" rel="noreferrer">GitHub</a>. Erros e sugestões: <a href="https://github.com/thalesmaoa/magfem/issues" target="_blank" rel="noreferrer">issues</a>.</li></ul><p>Abra em <a href="https://thalesmaia.com/tools/magfem-web/" target="_blank" rel="noreferrer">https://thalesmaia.com/tools/magfem-web/</a>. Funciona melhor no Chrome ou no Edge, que permitem salvar direto no mesmo arquivo; no Firefox e no Safari, salvar vira download.</p><h2 id="o-fluxo-de-trabalho" tabindex="-1">O fluxo de trabalho <a class="header-anchor" href="#o-fluxo-de-trabalho" aria-label="Permalink to &quot;O fluxo de trabalho&quot;">​</a></h2><p>A árvore à esquerda segue a ordem do trabalho, como no COMSOL:</p><ol><li><strong>Geometria</strong> — o desenho paramétrico (entidades, restrições, cotas e variáveis).</li><li><strong>Malha</strong> — materiais das regiões, circuitos, contornos, tamanho dos elementos e a malha.</li><li><strong>Método de resolução</strong> — a física (campo magnético ou circuito) e o tipo de análise.</li><li><strong>Resultados</strong> — vistas de campo, gráficos e tabelas, cada uma numa aba do canvas.</li></ol><p><img src="'+o+'" alt="Interface do MagFEM com um campo resolvido" class="shot"></p><h2 id="a-interface" tabindex="-1">A interface <a class="header-anchor" href="#a-interface" aria-label="Permalink to &quot;A interface&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Área</th><th>O que tem</th></tr></thead><tbody><tr><td>Barra superior</td><td>Novo, Abrir, Salvar, Salvar como, Importar, Exportar, Citar, idioma (PT/EN) e tema</td></tr><tr><td>Barra de ferramentas</td><td>desenho, restrições, cota e edição (tesoura, offset, espelho, padrões), mover e agrupar</td></tr><tr><td>Árvore do modelo</td><td>as quatro etapas; o <code>+</code> de cada nó cria itens; duplo clique renomeia</td></tr><tr><td>Propriedades</td><td>abaixo da árvore: as propriedades do que está selecionado</td></tr><tr><td>Canvas</td><td>o desenho e as abas de resultados (vistas, gráficos, tabelas, esquemático)</td></tr><tr><td>Gaveta da direita</td><td><strong>Problema e bibliotecas</strong>: unidade, plano/axissimétrico, profundidade, materiais e contornos</td></tr><tr><td>Console</td><td>cada ação aparece como comando da API; também aceita comandos digitados</td></tr><tr><td>Barra de status</td><td>coordenadas, graus de liberdade, dicas, <strong>Script local</strong>, Bug reports e a versão</td></tr></tbody></table><h2 id="proximos-passos" tabindex="-1">Próximos passos <a class="header-anchor" href="#proximos-passos" aria-label="Permalink to &quot;Próximos passos&quot;">​</a></h2><ul><li>Faça o <a href="./first-model.html">primeiro modelo</a>: uma bobina axissimétrica com núcleo de aço, do desenho à indutância.</li><li>Veja como desenhar e restringir a <a href="./geometry.html">geometria</a>.</li><li>Automatize com o <a href="./../scripting/console.html">console</a> e a <a href="./../scripting/bridge.html">ponte local</a>.</li></ul>',12)])])}const f=e(i,[["render",d]]);export{h as __pageData,f as default};
